const projPt = (ll) => {
  if (!ll) return null;
  const [lon, lat] = ll;
  return [
    ((lon - MAP.west) / (MAP.east - MAP.west)) * MAP.W,
    ((MAP.north - lat) / (MAP.north - MAP.south)) * MAP.H,
  ];
};

